import numpy as np
import pandas as pd
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler, PolynomialFeatures
from sklearn.feature_selection import SelectKBest, f_classif
from datetime import datetime
import json

class FeatureStore:
    def __init__(self):
        self.features = {}
        self.pipelines = {}
        self.metadata = {}

    def register_feature(self, name, pipeline, description, version='1.0'):
        self.features[name] = pipeline
        self.pipelines[name] = pipeline
        self.metadata[name] = {
            'name': name,
            'description': description,
            'version': version,
            'created_at': datetime.now().isoformat(),
            'steps': [step[0] for step in pipeline.steps]
        }
        return self

    def get_feature(self, name, X):
        if name not in self.features:
            raise KeyError(f"Feature '{name}' not found in store")
        return self.features[name].transform(X)

    def get_all_features(self, X):
        results = {}
        for name, pipeline in self.features.items():
            results[name] = pipeline.transform(X)
        return results

    def fit_all(self, X, y=None):
        for name, pipeline in self.features.items():
            self.features[name] = pipeline.fit(X, y)
        return self

    def export_spec(self):
        return {
            'feature_count': len(self.features),
            'features': self.metadata
        }

# Test Feature Store
np.random.seed(42)
X = np.random.randn(200, 10)
y = np.random.randint(0, 2, 200)

store = FeatureStore()

# Register features
store.register_feature(
    'scaled',
    Pipeline([('scaler', StandardScaler())]),
    'Standard scaled features'
)

store.register_feature(
    'poly',
    Pipeline([
        ('scaler', StandardScaler()),
        ('poly', PolynomialFeatures(degree=2, include_bias=False))
    ]),
    'Polynomial features (degree 2)'
)

store.register_feature(
    'selected',
    Pipeline([
        ('scaler', StandardScaler()),
        ('select', SelectKBest(f_classif, k=5))
    ]),
    'Top 5 features by ANOVA F-test'
)

# Fit all features
store.fit_all(X, y)

# Retrieve features
scaled = store.get_feature('scaled', X)
selected = store.get_feature('selected', X)

print(f"Feature Store Results:")
print(f"  Registered features: {list(store.metadata.keys())}")
print(f"  Scaled shape: {scaled.shape}")
print(f"  Selected shape: {selected.shape}")

spec = store.export_spec()
print(f"\nFeature Store Specification:")
print(json.dumps(spec, indent=2))
